s14-introduction-to-binary-search-tree.code:
// Approach: A strict BST keeps every left-subtree value below its root and every right-subtree value
//   above it. Its inorder traversal is sorted.
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
void bstInorder(TreeNode* node, vector<int>& sorted) {
    if (!node) return;
    bstInorder(node->left, sorted);
    sorted.push_back(node->val); // BST invariant yields ascending order
    bstInorder(node->right, sorted);
}
vector<int> sortedValues(TreeNode* root) {
    vector<int> answer;
    bstInorder(root, answer);
    return answer;
}

s14-search-in-a-binary-search-tree.code:
// Approach: Compare with the current node: go left for smaller values and right for larger values.
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
TreeNode* searchBST(TreeNode* root, int target) {
    // BST order lets us discard one subtree at each step.
    while (root) {
        if (root->val == target) return root;
        root = target < root->val ? root->left : root->right;
    }
    return nullptr;
}

s14-find-min-max-in-bst.code:
// Approach: The leftmost node is minimum and the rightmost node is maximum in a nonempty BST.
#include <utility>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
pair<TreeNode*, TreeNode*> minMaxBST(TreeNode* root) {
    if (!root) return {nullptr, nullptr};
    // The minimum is the leftmost node; the maximum is the rightmost.
    TreeNode* smallest = root;
    TreeNode* largest = root;
    while (smallest->left) smallest = smallest->left;
    while (largest->right) largest = largest->right;
    return {smallest, largest};
}

s14-ceil-in-a-binary-search-tree.code:
// Approach: Seek the smallest value at least x. When a node qualifies, remember it and look left for
//   a closer answer.
#include <optional>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
optional<int> ceilBST(TreeNode* root, int x) {
    optional<int> answer;
    while (root) {
        if (root->val == x) return x;
        if (root->val > x) {
            answer = root->val; // may find a smaller qualifying value on left
            root = root->left;
        } else root = root->right;
    }
    return answer; // nullopt if no value >= x exists
}

s14-floor-in-a-binary-search-tree.code:
// Approach: Seek the largest value at most x. When a node qualifies, remember it and look right for a
//   closer answer.
#include <optional>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
optional<int> floorBST(TreeNode* root, int x) {
    optional<int> answer;
    while (root) {
        if (root->val == x) return x;
        if (root->val < x) {
            answer = root->val; // may find a larger qualifying value on right
            root = root->right;
        } else root = root->left;
    }
    return answer; // nullopt if no value <= x exists
}

s14-insert-a-given-node-in-binary-search.code:
// Approach: Follow comparisons until reaching an empty child link and create the node there. This
//   strict-BST version ignores duplicate values.
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
TreeNode* insertIntoBST(TreeNode* root, int value) {
    if (!root) return new TreeNode{value, nullptr, nullptr};
    TreeNode* current = root;
    while (true) {
        if (value == current->val) break; // keep values unique
        TreeNode*& child = value < current->val
            ? current->left : current->right;
        if (!child) {
            child = new TreeNode{value, nullptr, nullptr};
            break;
        }
        current = child;
    }
    return root;
}

s14-delete-a-node-in-binary-search-tree.code:
// Approach: Find the target by BST comparison. If it has two children, replace its value with its
//   inorder successor, then remove that successor.
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
TreeNode* deleteNode(TreeNode* root, int key) {
    // After finding the value, preserve BST order when joining its children.
    if (!root) return nullptr;
    if (key < root->val) {
        root->left = deleteNode(root->left, key);
    } else if (key > root->val) {
        root->right = deleteNode(root->right, key);
    } else {
        if (!root->left || !root->right) {
            TreeNode* child = root->left ? root->left : root->right;
            delete root;
            return child;
        }
        TreeNode* successor = root->right;
        while (successor->left) successor = successor->left;
        root->val = successor->val;
        root->right = deleteNode(root->right, successor->val);
    }
    return root;
}

s14-find-k-th-smallest-largest-element-i.code:
// Approach: Inorder yields ascending values and reverse inorder descending values. Stop after
//   visiting k nodes rather than storing the full traversal.
#include <optional>
#include <stack>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
optional<int> kthBST(TreeNode* root, int k, bool largest) {
    if (k <= 0) return nullopt;
    stack<TreeNode*> pending;
    TreeNode* current = root;
    while (current || !pending.empty()) {
        while (current) {
            pending.push(current);
            current = largest ? current->right : current->left;
        }
        current = pending.top(); pending.pop();
        if (--k == 0) return current->val;
        current = largest ? current->left : current->right;
    }
    return nullopt; // fewer than k nodes
}

s14-check-if-a-tree-is-a-bst-or-bt.code:
// Approach: A node must lie strictly between bounds inherited from all its ancestors, not only be
//   ordered against its immediate children.
#include <climits>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
bool validRange(TreeNode* node, long long low, long long high) {
    // Each subtree must stay inside the allowed value bounds.
    if (!node) return true;
    if (node->val <= low || node->val >= high) return false;
    return validRange(node->left, low, node->val)
        && validRange(node->right, node->val, high);
}
bool isValidBST(TreeNode* root) {
    return validRange(root, LLONG_MIN, LLONG_MAX);
}

s14-lca-in-binary-search-tree.code:
// Approach: If both targets are below the current value, go left; if both are above, go right. The
//   first split point is their LCA.
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
TreeNode* lcaBST(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (!p || !q) return nullptr;
    while (root) {
        if (p->val < root->val && q->val < root->val)
            root = root->left;
        else if (p->val > root->val && q->val > root->val)
            root = root->right;
        else return root; // paths diverge here, or one target is here
    }
    return nullptr; // assumes both targets belong to this BST
}

s14-construct-a-bst-from-a-preorder-trav.code:
// Approach: Consume preorder once. Each recursive subtree accepts only values within its allowed
//   lower and upper BST bounds.
#include <climits>
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
TreeNode* buildWithin(const vector<int>& pre, int& i,
                      long long low, long long high) {
    if (i == (int)pre.size() || pre[i] <= low || pre[i] >= high)
        return nullptr;
    int value = pre[i++];
    TreeNode* root = new TreeNode{value, nullptr, nullptr};
    // All left-subtree values must be smaller than the root.
    root->left = buildWithin(pre, i, low, value);
    root->right = buildWithin(pre, i, value, high);
    return root;
}
TreeNode* bstFromPreorder(const vector<int>& preorder) {
    int i = 0;
    TreeNode* root = buildWithin(preorder, i, LLONG_MIN, LLONG_MAX);
    return root;
}

s14-inorder-successor-predecessor-in-bst.code:
// Approach: While searching for x, a smaller node is a predecessor candidate and a larger node is a
//   successor candidate; move toward x for tighter bounds.
#include <utility>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
pair<TreeNode*, TreeNode*> predecessorSuccessor(TreeNode* root, int x) {
    TreeNode* predecessor = nullptr;
    TreeNode* successor = nullptr;
    while (root) {
        if (root->val < x) {
            predecessor = root;
            root = root->right;
        } else if (root->val > x) {
            successor = root;
            root = root->left;
        } else {
            TreeNode* p = root->left;
            while (p) { predecessor = p; p = p->right; }
            TreeNode* s = root->right;
            while (s) { successor = s; s = s->left; }
            break;
        }
    }
    return {predecessor, successor}; // strict bounds, even if x is absent
}

s14-merge-2-bst-s.code:
// Approach: Maintain an inorder stack for each tree. Repeatedly take the smaller next value and
//   advance only that tree.
#include <stack>
#include <vector>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
void pushLeft(TreeNode* node, stack<TreeNode*>& pending) {
    // Inorder traversal yields sorted values from each BST.
    while (node) { pending.push(node); node = node->left; }
}
vector<int> mergeBSTs(TreeNode* a, TreeNode* b) {
    stack<TreeNode*> first, second;
    pushLeft(a, first);
    pushLeft(b, second);
    vector<int> answer;
    while (!first.empty() || !second.empty()) {
        stack<TreeNode*>& chosen = second.empty() ||
            (!first.empty() && first.top()->val <= second.top()->val)
            ? first : second;
        TreeNode* node = chosen.top(); chosen.pop();
        answer.push_back(node->val);
        pushLeft(node->right, chosen);
    }
    return answer;
}

s14-two-sum-in-bst-check-if-there-exists.code:
// Approach: Use one inorder iterator from the minimum and another in reverse from the maximum. Move
//   the side that makes the sum approach the target.
#include <stack>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
class BSTIterator {
    // This iterator yields BST values in ascending or descending order.
    stack<TreeNode*> pending;
    bool reverse;
    void pushPath(TreeNode* node) {
        while (node) {
            pending.push(node);
            node = reverse ? node->right : node->left;
        }
    }
public:
    BSTIterator(TreeNode* root, bool reverse) : reverse(reverse) {
        pushPath(root);
    }
    TreeNode* next() {
        if (pending.empty()) return nullptr;
        TreeNode* node = pending.top(); pending.pop();
        pushPath(reverse ? node->left : node->right);
        return node;
    }
};
bool findTarget(TreeNode* root, long long target) {
    if (!root) return false;
    BSTIterator ascending(root, false), descending(root, true);
    TreeNode* left = ascending.next();
    TreeNode* right = descending.next();
    while (left && right && left != right && left->val < right->val) {
        long long sum = (long long)left->val + right->val;
        if (sum == target) return true;
        // Move the ascending iterator for a larger sum, otherwise move descending.
        if (sum < target) left = ascending.next();
        else right = descending.next();
    }
    return false;
}

s14-recover-bst-correct-bst-with-two-nod.code:
// Approach: Morris inorder traversal detects out-of-order neighboring values while using temporary
//   threads. The first wrong predecessor and last wrong current node are swapped.
#include <utility>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
void recoverTree(TreeNode* root) {
    TreeNode *first = nullptr, *second = nullptr, *previous = nullptr;
    TreeNode* current = root;
    auto visit = [&](TreeNode* node) {
        // A descending adjacent pair in inorder reveals swapped values.
        if (previous && previous->val > node->val) {
            if (!first) first = previous;
            second = node; // updates on a second inversion too
        }
        previous = node;
    };
    while (current) {
        if (!current->left) {
            visit(current);
            current = current->right;
        } else {
            TreeNode* predecessor = current->left;
            while (predecessor->right && predecessor->right != current)
                predecessor = predecessor->right;
            if (!predecessor->right) {
                predecessor->right = current;
                current = current->left;
            } else {
                predecessor->right = nullptr; // restore the tree
                visit(current);
                current = current->right;
            }
        }
    }
    if (first && second) swap(first->val, second->val);
}

s14-largest-bst-in-binary-tree.code:
// Approach: For each subtree return its minimum, maximum, and size. It forms a BST only if its root
//   exceeds the left maximum and is below the right minimum.
#include <algorithm>
#include <climits>
using namespace std;
struct TreeNode { int val; TreeNode* left; TreeNode* right; };
struct SubtreeInfo {
    long long smallest, largest;
    int size;
};
SubtreeInfo largestBstDfs(TreeNode* node, int& best) {
    if (!node) return {LLONG_MAX, LLONG_MIN, 0};
    SubtreeInfo left = largestBstDfs(node->left, best);
    SubtreeInfo right = largestBstDfs(node->right, best);
    if (left.largest < node->val && node->val < right.smallest) {
        int size = left.size + right.size + 1;
        best = max(best, size);
        return {min(left.smallest, (long long)node->val),
                max(right.largest, (long long)node->val), size};
    }
    return {LLONG_MIN, LLONG_MAX, 0}; // invalid: ancestors cannot use it
}
int largestBSTSubtree(TreeNode* root) {
    int best = 0;
    largestBstDfs(root, best);
    return best;
}
